def _add_paths(parser: argparse.ArgumentParser, signing: bool = False) -> None:
    """The shared location options; each defaults to the AIKit workspace layout (ADR-003)."""
    parser.add_argument("--register", default=None, metavar="PATH",
                        help="Public register (default: ../aegean-licensing/licenses/issued.json).")
    parser.add_argument("--db", default=None, metavar="PATH", help="Database (default: data/ops.sqlite3).")
    parser.add_argument("--output-dir", default=None, metavar="PATH",
                        help="Where certificate files are written (default: data/certs).")
    parser.add_argument("--json", action="store_true", help="Answer with one JSON object on stdout.")
    if signing:
        signer_group = parser.add_mutually_exclusive_group()
        signer_group.add_argument("--key", default=None, help="Secret HMAC signing key (prefer --key-file).")
        signer_group.add_argument("--key-file", default=None, metavar="PATH",
                                  help="File holding the signing key (default: ~/.aegean/signing.key).")


def _settings(args: argparse.Namespace) -> operations.OpsSettings:
    return operations.default_settings(args.register, getattr(args, "key_file", None),
                                       args.output_dir, args.db)


def _signing_key(args: argparse.Namespace, settings: operations.OpsSettings) -> str:
    """--key, else --key-file, else the default key file; no key at all is an error."""
    if args.key:
        return args.key
    if not args.key_file and not settings.key_file.is_file():
        raise ValueError(f"a signing key is required: pass --key-file or --key, or keep it in {settings.key_file}.")
    return operations.read_signing_key(settings.key_file)


def _emit(args: argparse.Namespace, result: Any, lines: Sequence[str]) -> None:
    if args.json:
        print(json.dumps({"ok": True, "result": result}, indent=2, default=str))
    else:
        for line in lines:
            print(line)


def _fail(args: argparse.Namespace, message: str) -> int:
    if args.json:
        print(json.dumps({"ok": False, "error": message}))
    else:
        print(f"Error: {message}", file=sys.stderr)
    return 1


def _handle_issue(args: argparse.Namespace) -> int:
    settings = _settings(args)
    try:
        result = operations.issue(
            settings, _signing_key(args, settings), licensee_name=args.licensee,
