def _handle_records(args: argparse.Namespace) -> int:
    """list, edit, backup and erase: the database commands."""
    settings = _settings(args)
    try:
        with contextlib.closing(database.connect(settings.db_path)) as connection:
            if args.command == "list":
                records = database.list_records(connection, status=args.status, search=args.search)
                for record in records:
                    record.pop("certificate_json", None)
                _emit(args, {"certificates": records}, [
                    f"{r['cert_id']}  {r['status']:<7}  {r['issued_at']}  {r['licensee_name']}  "
                    f"<{r['current_contact']}>" for r in records] or ["No certificates."])
            elif args.command == "edit":
                fields = {k: v for k, v in (("current_contact", args.contact), ("internal_notes", args.notes))
                          if v is not None}
                if not fields:
                    raise ValueError("give --contact and/or --notes.")
                record = database.update_record(connection, args.cert_id, **fields)
                record.pop("certificate_json", None)
                _emit(args, {"certificate": record}, [f"Updated {args.cert_id}."])
            elif args.command == "backup":
                target = database.backup(connection, args.to)
                _emit(args, {"backup": str(target)}, [f"Backed up the database to {target}."])
            else:
                if not args.yes:
                    raise ValueError("erasing personal data cannot be undone; add --yes to confirm.")
                record = database.erase_personal_data(connection, args.cert_id)
                record.pop("certificate_json", None)
                _emit(args, {"certificate": record},
                      [f"Erased the personal data of {args.cert_id}; id, serial, dates and status remain."])
    except (OSError, ValueError) as exc:
        return _fail(args, str(exc))
    return 0


